"""AST node definitions shared by the parser and the execution engine.

Every expression node has a ``text`` attribute containing the exact source
text of that expression (as written in the query).  It is a plain class
attribute rather than a dataclass field so that node equality is structural
and ignores formatting.
"""

from dataclasses import dataclass, field
from typing import Any, List, Optional


class Expr:
    """Base class for all expression nodes."""

    text = ""


@dataclass
class Literal(Expr):
    value: Any


@dataclass
class Name(Expr):
    name: str


@dataclass
class Star(Expr):
    """The ``*`` wildcard (only valid as a select item or ``COUNT(*)``)."""


@dataclass
class Unary(Expr):
    op: str  # "-" or "NOT"
    operand: Expr


@dataclass
class Binary(Expr):
    op: str  # arithmetic, comparison, "AND", "OR", "||"
    left: Expr
    right: Expr


@dataclass
class IsNull(Expr):
    operand: Expr
    negated: bool = False


@dataclass
class In(Expr):
    operand: Expr
    items: List[Expr] = field(default_factory=list)
    negated: bool = False


@dataclass
class Between(Expr):
    operand: Expr
    low: Expr
    high: Expr
    negated: bool = False


@dataclass
class Like(Expr):
    operand: Expr
    pattern: Expr
    negated: bool = False


@dataclass
class Func(Expr):
    name: str
    args: List[Expr] = field(default_factory=list)


@dataclass
class Column:
    """A select-list item."""

    expr: Expr
    alias: Optional[str] = None


@dataclass
class OrderItem:
    expr: Expr
    desc: bool = False


@dataclass
class Select:
    distinct: bool
    columns: List[Column]
    table: str
    where: Optional[Expr] = None
    group_by: List[Expr] = field(default_factory=list)
    having: Optional[Expr] = None
    order_by: List[OrderItem] = field(default_factory=list)
    limit: Optional[int] = None
    offset: Optional[int] = None

