"""SQL value semantics: NULL logic, operators, functions, and aggregates.

Public interface used by the engine.  Implementations must raise
:class:`minisql.errors.QueryError` for type errors and unknown functions.
"""

from typing import Any, List, Optional


def and3(a: Optional[bool], b: Optional[bool]) -> Optional[bool]:
    """Three-valued AND."""


def or3(a: Optional[bool], b: Optional[bool]) -> Optional[bool]:
    """Three-valued OR."""


def not3(a: Optional[bool]) -> Optional[bool]:
    """Three-valued NOT."""


def condition(value: Any) -> bool:
    """Interpret a value used by WHERE/HAVING: only TRUE keeps a row."""


def arithmetic(op: str, a: Any, b: Any) -> Any:
    """Apply ``+``, ``-``, ``*`` or ``/`` with SQL typing and NULL rules."""


def negate(a: Any) -> Any:
    """Unary minus."""


def concat(a: Any, b: Any) -> Any:
    """The ``||`` operator."""


def compare(op: str, a: Any, b: Any) -> Optional[bool]:
    """Apply ``= != <> < <= > >=`` returning None for a NULL operand."""


def like(value: Any, pattern: Any) -> Optional[bool]:
    """SQL LIKE over the whole string, case-sensitive."""


def in_list(value: Any, items: List[Any]) -> Optional[bool]:
    """SQL ``value IN (items...)`` with NULL semantics."""


def between(value: Any, low: Any, high: Any) -> Optional[bool]:
    """SQL ``value BETWEEN low AND high`` with NULL semantics."""


def scalar_function(name: str, args: List[Any]) -> Any:
    """Call a scalar function.  ``args`` are already evaluated."""


def is_aggregate(name: str) -> bool:
    """Return True for COUNT/SUM/AVG/MIN/MAX (case-insensitive)."""


def aggregate(name: str, values: List[Any]) -> Any:
    """Aggregate already-evaluated argument values (NULLs included).

    ``COUNT(*)`` is handled by the engine; for ``COUNT(expr)`` pass the
    per-row values and this counts non-NULL ones.
    """


def compare_for_sort(a: Any, b: Any) -> int:
    """Compare two non-NULL values, returning -1, 0, or 1."""


def group_key(value: Any) -> Any:
    """Return a hashable key such that SQL-equal values share a key."""


def row_key(values: List[Any]) -> tuple:
    """Return a hashable key for a whole row of values."""


def to_text(value: Any) -> str:
    """Text representation used by ``||`` and output formatting."""

